// [REQ-002] [REQ-005] restart the lock delay, at most MAX_LOCK_RESETS times per piece
function restartLockDelay() {
  var cur = state.current;
  if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
}

// [REQ-002] sideways move; while resting it restarts the lock delay
function shift(dc) {
  var resting = !canMove(1, 0);
  if (tryMove(0, dc) && resting) restartLockDelay();
}

// [REQ-003] [REQ-005] soft drop scores per cell; on a resting piece it restarts the lock delay like a sideways move
function softDrop() {
  if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
  else restartLockDelay();
}

